import React, { Suspense } from "react";
import { Canvas } from "@react-three/fiber";
import { Splat, OrbitControls } from "@react-three/drei";
import { useNavigate } from "react-router-dom";

const SplatPage = () => {
  const navigate = useNavigate();

  return (
    <div style={{ width: "100vw", height: "100vh", background: "#111", position: "relative" }}>
      <Canvas camera={{ position: [0, 0, 3], fov: 60 }} style={{ width: "100%", height: "100%" }}>
        <Suspense fallback={null}>
          <Splat src={process.env.PUBLIC_URL + "/my_table.splat"} />
        </Suspense>
        <OrbitControls />
      </Canvas>
      <div style={{ position: "absolute", top: "20px", left: "20px" }}>
        <button
          onClick={() => navigate(-1)}
          style={{
            background: "rgba(255,255,255,0.15)",
            border: "1px solid rgba(255,255,255,0.3)",
            color: "#fff",
            padding: "8px 16px",
            borderRadius: "8px",
            cursor: "pointer",
            backdropFilter: "blur(8px)",
            fontSize: "14px",
          }}
        >
          ← Back
        </button>
      </div>
      <div style={{ position: "absolute", bottom: "20px", left: "50%", transform: "translateX(-50%)", color: "rgba(255,255,255,0.4)", fontSize: "13px" }}>
        Drag to orbit · Scroll to zoom · Right-click to pan
      </div>
    </div>
  );
};

export default SplatPage;
